  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "song_id",
   "type": "integer",
   "required": false,
   "description": "ID of the song to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "album_id",
   "type": "integer",
   "required": false,
   "description": "ID of the album to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "playlist_id",
   "type": "integer",
   "required": false,
   "description": "ID of the playlist to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "queue_position",
   "type": "integer",
   "required": false,
   "description": "Position of the song in the queue to play.",
   "default": null,
   "constraints": [
    "value >= 0.0"
   ]
  }
 ],
 "response_schemas": {
